# Library catalogue: single source for 17-libraries_review-list.md and the review page.
# Facts from three research agents (2026-10-01); top-tier rows re-verified by the main session the same day.
CATS = [
 ("ui","UI components","Platform matters most here. daisyUI and Basecoat work everywhere. The React family (shadcn, Base UI, Magic UI) needs React, and costs JavaScript on Astro."),
 ("motion","Animation, scroll and transitions","Order of preference: CSS first, then the reveal snippet, then one JS library. Podium, your reference site, ships about 608 KB of JavaScript, hides the page behind a loading screen and never checks reduced motion. Copy its ideas, not its weight."),
 ("webgl","WebGL, 3D and backgrounds","Most clients should get the CSS background, not WebGL. WebGL is justified for a product buyers want to turn around (model-viewer) or a brand-led hero (Paper Shaders). A custom three.js scene is an estimated 20 to 60 hours, so quote it as a separate line item."),
 ("text","Text effects","Splitting text into letters breaks screen readers unless the full sentence stays readable. SplitType and Splitting.js fail that test and are excluded."),
 ("icons","Icons","Default to Lucide and fill gaps with Tabler. Both sit on the same 24px grid, so they mix cleanly."),
 ("charts","Charts","Brochure sites rarely need charts. The clients that do: solar and energy installers, property, NGOs, consultancies, training providers, tourism and events."),
]
L = []
def add(**k): L.append(k)

